package com.college.scholarship;

import jakarta.servlet.http.HttpSession;
import java.math.BigDecimal;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.nio.file.*;
import java.io.IOException;
import org.springframework.core.io.Resource;
import org.springframework.core.io.UrlResource;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;

@RestController @RequestMapping("/api/admin")
public class AdminController {
    private final JdbcTemplate jdbc;
    public AdminController(JdbcTemplate jdbc){this.jdbc=jdbc;}
    @GetMapping("/applications") public List<Map<String,Object>> applications(@RequestParam(required=false) String status,HttpSession session){admin(session);String sql="SELECT a.id,a.application_date,a.status,a.admin_remarks,u.full_name,u.email,s.name AS scholarship_name FROM scholarship_applications a JOIN users u ON u.id=a.user_id JOIN scholarships s ON s.id=a.scholarship_id";return status==null?jdbc.queryForList(sql+" ORDER BY a.application_date DESC"):jdbc.queryForList(sql+" WHERE a.status=? ORDER BY a.application_date DESC",status);}
    @GetMapping("/students") public List<Map<String,Object>> students(HttpSession s){admin(s);return jdbc.queryForList("SELECT u.id AS user_id,u.full_name,u.email,p.academic_year,p.course_type,p.course_name,p.current_year,p.institution_name,p.institution_approval_status,p.institution_approval_verified,p.admission_route,p.admission_route_verified,p.qualifying_board,p.qualifying_merit_position,p.qualifying_conditions_verified FROM users u JOIN student_profiles p ON p.user_id=u.id WHERE u.role='STUDENT' ORDER BY u.full_name");}
    @PutMapping("/students/{userId}/verification") @Transactional public Map<String,String> verifyProfile(@PathVariable long userId,@RequestBody ProfileVerification v,HttpSession s){long admin=admin(s);if(v.remarks()==null||v.remarks().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Verification remarks are required.");if(v.institutionApprovalStatus()!=null&&!Set.of("APPROVED","PENDING","NOT_APPROVED","NOT_APPLICABLE").contains(v.institutionApprovalStatus()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported institution approval status.");int changed=jdbc.update("UPDATE student_profiles SET institution_approval_status=?,institution_approval_verified=?,admission_route_verified=?,qualifying_conditions_verified=? WHERE user_id=?",v.institutionApprovalStatus(),v.institutionApprovalStatus()!=null,v.admissionRouteVerified(),v.qualifyingConditionsVerified(),userId);if(changed==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Student profile not found.");jdbc.update("INSERT INTO student_profile_verification_history(user_id,verified_by,institution_approval_status,institution_approval_verified,admission_route_verified,qualifying_conditions_verified,remarks) VALUES(?,?,?,?,?,?,?)",userId,admin,v.institutionApprovalStatus(),v.institutionApprovalStatus()!=null,v.admissionRouteVerified(),v.qualifyingConditionsVerified(),v.remarks());return Map.of("message","Student verification recorded.");}
    @PutMapping("/applications/{id}/status") @Transactional
    public Map<String,String> decide(@PathVariable long id,@RequestBody Decision d,HttpSession session){
        long admin=admin(session);
        if(!Set.of("UNDER_REVIEW","NEEDS_CORRECTION","APPROVED","REJECTED").contains(d.status()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported status.");
        var rows=jdbc.query("SELECT status,scholarship_id FROM scholarship_applications WHERE id=? FOR UPDATE",(r,n)->new Object[]{r.getString(1),r.getLong(2)},id);
        if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Application not found.");
        String old=(String)rows.get(0)[0];long scholarshipId=(Long)rows.get(0)[1];
        Map<String,Set<String>> transitions=Map.of("SUBMITTED",Set.of("UNDER_REVIEW","NEEDS_CORRECTION","APPROVED","REJECTED"),"UNDER_REVIEW",Set.of("NEEDS_CORRECTION","APPROVED","REJECTED"),"NEEDS_CORRECTION",Set.of("UNDER_REVIEW","REJECTED"));
        if(!transitions.getOrDefault(old,Set.of()).contains(d.status()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invalid status transition from "+old+" to "+d.status()+".");
        if(d.remarks()==null||d.remarks().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Please provide review remarks.");
        if(d.status().equals("APPROVED")){
            Integer required=jdbc.queryForObject("SELECT COUNT(*) FROM scholarship_documents WHERE scholarship_id=?",Integer.class,scholarshipId);
            Integer verified=jdbc.queryForObject("SELECT COUNT(DISTINCT sd.document_name) FROM scholarship_documents sd JOIN application_documents d ON d.document_type=sd.document_name AND d.verification_status='VERIFIED' WHERE sd.scholarship_id=? AND d.application_id=?",Integer.class,scholarshipId,id);
            if(required>0&&verified<required)throw new ResponseStatusException(HttpStatus.CONFLICT,"Verify all required documents before approval.");
        }
        jdbc.update("UPDATE scholarship_applications SET status=?,admin_remarks=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=?",d.status(),d.remarks(),admin,id);
        jdbc.update("INSERT INTO scholarship_application_history(application_id,previous_status,new_status,changed_by,remarks) VALUES(?,?,?,?,?)",id,old,d.status(),admin,d.remarks());
        return Map.of("message","Application updated.");
    }
    @GetMapping("/scholarships") public List<Map<String,Object>> scholarships(HttpSession s){admin(s);return jdbc.queryForList("SELECT * FROM scholarships ORDER BY academic_year DESC,name");}
    @GetMapping("/scholarships/{id}") public Map<String,Object> scholarship(@PathVariable long id,HttpSession s){admin(s);var rows=jdbc.queryForList("SELECT * FROM scholarships WHERE id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Scholarship not found.");Map<String,Object> result=new LinkedHashMap<>(rows.get(0));result.put("courseTypes",jdbc.query("SELECT DISTINCT course_type FROM scholarship_courses WHERE scholarship_id=?",(r,n)->r.getString(1),id));result.put("courseNames",jdbc.query("SELECT DISTINCT course_name FROM scholarship_courses WHERE scholarship_id=?",(r,n)->r.getString(1),id));result.put("studyYears",jdbc.query("SELECT study_year FROM scholarship_years WHERE scholarship_id=?",(r,n)->r.getInt(1),id));result.put("categories",jdbc.query("SELECT category FROM scholarship_categories WHERE scholarship_id=?",(r,n)->r.getString(1),id));result.put("genders",jdbc.query("SELECT gender FROM scholarship_genders WHERE scholarship_id=?",(r,n)->r.getString(1),id));result.put("states",jdbc.query("SELECT state_name FROM scholarship_states WHERE scholarship_id=?",(r,n)->r.getString(1),id));result.put("documents",jdbc.query("SELECT document_name FROM scholarship_documents WHERE scholarship_id=?",(r,n)->r.getString(1),id));result.put("additionalRules",jdbc.query("SELECT rule_code,description,required,verified FROM scholarship_rules WHERE scholarship_id=?",(r,n)->new EligibilityRule(r.getString(1),r.getString(2),r.getBoolean(3),r.getBoolean(4)),id));return result;}
    @PatchMapping("/scholarships/{id}/active") public Map<String,String> setActive(@PathVariable long id,@RequestBody ActiveState state,HttpSession s){admin(s);if(jdbc.update("UPDATE scholarships SET active=? WHERE id=?",state.active(),id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Scholarship not found.");return Map.of("message",state.active()?"Scholarship activated.":"Scholarship deactivated.");}
    @PostMapping("/scholarships") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> createScholarship(@RequestBody ScholarshipInput x,HttpSession s){admin(s);validate(x);jdbc.update("INSERT INTO scholarships(scheme_code,name,administering_authority,description,academic_year,maximum_annual_family_income,minimum_previous_academic_percentage,scholarship_amount,application_deadline,official_information_url,criteria_verified,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",x.schemeCode(),x.name(),x.authority(),x.description(),x.academicYear(),x.maxIncome(),x.minPercentage(),x.amount(),x.deadline(),x.officialUrl(),x.verified(),x.active());Long id=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);replaceCriteria(id,x);return Map.of("id",id,"message","Scholarship created.");}
    @PutMapping("/scholarships/{id}") @Transactional public Map<String,String> updateScholarship(@PathVariable long id,@RequestBody ScholarshipInput x,HttpSession s){admin(s);validate(x);if(jdbc.update("UPDATE scholarships SET scheme_code=?,name=?,administering_authority=?,description=?,academic_year=?,maximum_annual_family_income=?,minimum_previous_academic_percentage=?,scholarship_amount=?,application_deadline=?,official_information_url=?,criteria_verified=?,active=? WHERE id=?",x.schemeCode(),x.name(),x.authority(),x.description(),x.academicYear(),x.maxIncome(),x.minPercentage(),x.amount(),x.deadline(),x.officialUrl(),x.verified(),x.active(),id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Scholarship not found.");replaceCriteria(id,x);return Map.of("message","Scholarship updated.");}
    private void replaceCriteria(long id,ScholarshipInput x){for(String t:List.of("scholarship_courses","scholarship_years","scholarship_categories","scholarship_genders","scholarship_states","scholarship_documents","scholarship_rules"))jdbc.update("DELETE FROM "+t+" WHERE scholarship_id=?",id);for(String v:x.courseTypes())for(String name:x.courseNames())jdbc.update("INSERT INTO scholarship_courses(scholarship_id,course_type,course_name) VALUES(?,?,?)",id,v,name);for(Integer v:x.studyYears())jdbc.update("INSERT INTO scholarship_years(scholarship_id,study_year) VALUES(?,?)",id,v);for(String v:x.categories())jdbc.update("INSERT INTO scholarship_categories(scholarship_id,category) VALUES(?,?)",id,v);for(String v:x.genders())jdbc.update("INSERT INTO scholarship_genders(scholarship_id,gender) VALUES(?,?)",id,v);for(String v:x.states())jdbc.update("INSERT INTO scholarship_states(scholarship_id,state_name) VALUES(?,?)",id,v);for(String v:safe(x.documents()))jdbc.update("INSERT INTO scholarship_documents(scholarship_id,document_name) VALUES(?,?)",id,v);for(EligibilityRule r:safe(x.additionalRules()))jdbc.update("INSERT INTO scholarship_rules(scholarship_id,rule_code,description,required,verified) VALUES(?,?,?,?,?)",id,r.code(),r.description(),r.required(),r.verified());}
    private <T> List<T> safe(List<T> values){return values==null?List.of():values;}
    private void validate(ScholarshipInput x){if(x.schemeCode()==null||x.schemeCode().isBlank()||x.name()==null||x.name().isBlank()||x.authority()==null||x.academicYear()==null||!x.academicYear().matches("20\\d{2}-\\d{2}")||x.description()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Scheme code, name, authority, valid academic year, and description are required.");if(x.courseTypes()==null||x.courseTypes().isEmpty()||x.courseNames()==null||x.courseNames().isEmpty()||x.studyYears()==null||x.studyYears().isEmpty()||x.categories()==null||x.categories().isEmpty()||x.genders()==null||x.genders().isEmpty()||x.states()==null||x.states().isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Every multi-value criterion must be supplied; use * to state that it is unrestricted.");if(x.studyYears().stream().anyMatch(v->v<1||v>4)||x.maxIncome()!=null&&x.maxIncome().signum()<0||x.minPercentage()!=null&&(x.minPercentage().signum()<0||x.minPercentage().compareTo(BigDecimal.valueOf(100))>0)||x.amount()!=null&&x.amount().signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Study year, income, amount, or percentage criteria are out of range.");if(x.categories().stream().anyMatch(v->!Set.of("*","GENERAL","OBC","SC","ST","MINORITY").contains(v))||x.genders().stream().anyMatch(v->!Set.of("*","MALE","FEMALE","OTHER").contains(v))||x.courseTypes().stream().anyMatch(v->!Set.of("*","UG","PG","DIPLOMA").contains(v)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A course, category, or gender criterion is unsupported.");if(safe(x.additionalRules()).stream().anyMatch(r->r==null||r.code()==null||r.code().isBlank()||r.description()==null||r.description().isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Each scheme rule needs a code and description.");}
    static long admin(HttpSession s){Object id=s.getAttribute("userId");if(id==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Login required.");if(!"ADMIN".equals(s.getAttribute("role")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Administrator role required.");return ((Number)id).longValue();}
    @GetMapping("/summary") public Map<String,Object> summary(HttpSession s){admin(s);return Map.of("activeScholarships",jdbc.queryForObject("SELECT COUNT(*) FROM scholarships WHERE active=TRUE",Integer.class),"pendingApplications",jdbc.queryForObject("SELECT COUNT(*) FROM scholarship_applications WHERE status IN ('SUBMITTED','UNDER_REVIEW')",Integer.class),"totalApplications",jdbc.queryForObject("SELECT COUNT(*) FROM scholarship_applications",Integer.class));}
    @GetMapping("/applications/{id}/documents") public List<Map<String,Object>> documents(@PathVariable long id,HttpSession s){admin(s);return jdbc.queryForList("SELECT id,document_type,original_filename,file_size,verification_status,verification_remarks,uploaded_at FROM application_documents WHERE application_id=?",id);}
    @PutMapping("/documents/{id}/verification") public Map<String,String> verifyDocument(@PathVariable long id,@RequestBody DocDecision d,HttpSession s){admin(s);if(!Set.of("VERIFIED","REJECTED").contains(d.status()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Verification status must be VERIFIED or REJECTED.");if(jdbc.update("UPDATE application_documents SET verification_status=?,verification_remarks=? WHERE id=?",d.status(),d.remarks(),id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found.");return Map.of("message","Document verification saved.");}
    @GetMapping("/applications/{applicationId}/documents/{documentId}/file") public ResponseEntity<Resource> download(@PathVariable long applicationId,@PathVariable long documentId,HttpSession s)throws IOException{admin(s);var row=jdbc.query("SELECT stored_filename,content_type,original_filename FROM application_documents WHERE id=? AND application_id=?",(r,n)->new String[]{r.getString(1),r.getString(2),r.getString(3)},documentId,applicationId);if(row.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found.");Path root=Path.of("uploads").toAbsolutePath().normalize();Path file=root.resolve(row.get(0)[0]).normalize();if(!file.startsWith(root)||!Files.exists(file))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Stored document not found.");Resource resource=new UrlResource(file.toUri());return ResponseEntity.ok().contentType(MediaType.parseMediaType(row.get(0)[1])).header("Content-Disposition","attachment; filename=\""+row.get(0)[2].replaceAll("[\\\"\\r\\n]","_")+"\"").body(resource);}
    record Decision(String status,String remarks){}
    record DocDecision(String status,String remarks){}
    record ActiveState(boolean active){}
    record ProfileVerification(String institutionApprovalStatus,boolean admissionRouteVerified,boolean qualifyingConditionsVerified,String remarks){}
    record ScholarshipInput(String schemeCode,String name,String authority,String description,String academicYear,BigDecimal maxIncome,BigDecimal minPercentage,BigDecimal amount,java.time.LocalDate deadline,String officialUrl,boolean verified,boolean active,List<String> courseTypes,List<String> courseNames,List<Integer> studyYears,List<String> categories,List<String> genders,List<String> states,List<String> documents,List<EligibilityRule> additionalRules){}
}
